-- 2026-10-13 おにぎりの紹介文を、店内メニュー「おにぎり帖」に合わせて変更
--
-- 実行方法: Supabase ダッシュボード → SQL Editor に貼り付けて Run
-- 16商品が更新されれば成功（コピー時に崩れないよう1行で書いている）

UPDATE products AS p SET description = v.description, updated_at = now() FROM (VALUES ('伊達の旨塩にぎり', '素材を活かす伊達な旨塩'), ('焼しゃけ', '毎朝店内で焼き上げる風味豊かなしゃけ'), ('おかチー', '当店一番人気!! おかかとチーズの驚きの相性'), ('えびマヨ', 'えび好きのあなたをときめかせたい'), ('おかか', 'ふわっと広がる手作りの甘み'), ('ツナマヨ', 'ツナから手作り 他では味わえない絶品'), ('辛子明太子', 'ピリッとやみつき プチプチの食感'), ('ルーロー', '台湾の人気グルメ 豚肉の甘辛煮'), ('茎わかめ佃煮', '石巻の旨みがあふれる味わいと食感'), ('鶏そぼろ', '生姜が香る甘辛ジューシー'), ('萩のしそひじき', '井上商店の名産品 山口県からお取り寄せ'), ('極み筋子', '店主こだわりの逸品 青森県からお取り寄せ'), ('ほぐし梅', '南高梅の豊かな香りとほどよい酸味がクセになる'), ('焼きおにぎり', '香ばしい味噌につい笑顔になる味'), ('ガパオ', 'ひと口でタイ旅行 鶏ひき肉のバジル炒め'), ('しゃけ筋子', '海からの贈り物をご堪能下さい')) AS v(name, description) WHERE p.name = v.name;
